import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import facts from'./legacy-2017-autumn-quality-facts.json';
const edges=[['S','A','A'],['A','U','B'],['A','C','C'],['C','U','D'],['U','M','E'],['C','M','F'],['C','B','G'],['M','H','H'],['M','I','I'],['B','I','J'],['H','Z','K'],['I','Z','L']] as const;
/** Independent exhaustive complete-route reference, not the producer's earliest-event calculation. */
export function qualityAllPaths(weights:Record<string,number>){const result:Record<string,number>={};function visit(node:string,path:string,total:number){if(node==='Z'){result[path]=total;return;}for(const[a,b,k]of edges)if(a===node)visit(b,path+k,total+weights[k]);}visit('S','',0);assert.equal(Object.keys(result).length,7);return result;}
const names:Record<string,string>={S:'左端の結合点',A:'中央段左の結合点',C:'中央段の左から二つ目の結合点',U:'上段左の結合点',M:'中央段の左から三つ目の結合点',B:'下段の結合点',H:'上段右の結合点',I:'中央段の左から四つ目の結合点',Z:'右端の結合点'};
export function qualityReviewedAlt(weights:Record<string,number>){return'9個の丸とAからLの12本の作業矢印。凡例では矢印の上が作業名、下が所要日数。'+edges.map(([a,b,k])=>`${names[a]}から${names[b]}へ、作業${k}、${weights[k]}日。`).join('');}
const text=(blocks:GeneratedBody['choices'][number])=>{assert.equal(blocks.length,1);const b=blocks[0];assert(b.type==='paragraph');return b.text;};
export function legacy2017AutumnQualityOracle(source:string,body:GeneratedBody,values:number[]){const n=Number(source.split('-').at(-1));let variant:number;
 if(n===58){assert.equal(values.length,4);assert(values.every(x=>Number.isInteger(x)&&[0,1].includes(x)));assert.equal(values.reduce((a,b)=>a+b,0),1);variant=[3,0,1,2].indexOf(values.indexOf(1));}else{assert.equal(values.length,1);assert(Number.isInteger(values[0]));variant=values[0];}
 const f=facts.conditions.find(r=>r.source===source&&r.variant===variant);assert(f);assert.equal(body.prompt.length,n===53?2:1);const p=body.prompt[0];assert(p.type==='paragraph');assert.equal(p.text,f.stem);assert.equal(body.choices.length,4);assert.deepEqual(body.choices.map(text),f.choices);assert.equal(body.explanation,f.explanation);
 let truth:boolean[];if(n===53){const w=f.diagram!.values,totals=qualityAllPaths(w),max=Math.max(...Object.values(totals)),best=Object.keys(totals).filter(k=>totals[k]===max);assert.equal(best.length,1);assert.deepEqual(totals,f.all7Paths);truth=f.choices.map(x=>x.replaceAll('→','')===best[0]);const b=body.prompt[1];assert(b.type==='diagram'&&b.scene.kind==='source_figure');assert.equal(b.scene.profile,'legacy-2017-project-critical-path');assert.deepEqual(b.scene.values,[variant]);assert.equal(b.caption,'プロジェクト活動と所要日数');assert.equal(b.alt,qualityReviewedAlt(w));}
 else if(n===58){truth=values.map(x=>x===1);assert.deepEqual(Object.values(f.slotFacts!),values);}
 else{const fixed=facts.primaryClassification.filter(r=>r.source===source&&r.variant===variant);assert.equal(fixed.length,4);truth=fixed.map(r=>r.classification===r.predicateTarget);}
 assert.deepEqual(truth,f.truth);assert.equal(truth.filter(Boolean).length,1);assert.equal(body.correctIndex,truth.indexOf(true));return truth;
}
export function qualityAuditDomain(){const out=[];for(let mask=0;mask<16;mask++){const values=[0,1,2,3].map(i=>(mask>>i)&1);out.push({values,valid:values.filter(Boolean).length===1});}return out;}
export function qualityCoverageWitness(){const paths=[[false,false],[false,true],[true,false],[true,true]],two=[paths[0],paths[3]],outcomes=new Set(two.flatMap(p=>p.map((b,i)=>`${i}:${b}`)));return{paths,two,outcomes:[...outcomes],branchCovered:outcomes.size,totalBranches:4,pathCovered:two.length,totalPaths:4};}
export function qualityRestoreWitness(){const baseline={x:1,y:2,z:3},delta1={x:10},delta2={y:20};return{baseline,delta1,delta2,fullAndDeltas:{...baseline,...delta1,...delta2},onlyDeltas:{...delta1,...delta2}};}
